<div class="card"><h1>Manage users</h1><form method="post"><?php hidden('add_user');?><div class="row"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input name="email" type="email" required></div></div><div class="row"><div><label>Department (must match for routing)</label><input name="department" required placeholder="Administration"></div><div><label>Role</label><select name="role"><option value="employee">Employee</option><option value="head">Department Head</option><option value="admin">Admin</option></select></div></div><label>Temporary password (10+ characters)</label><input type="password" name="password" minlength="10" required><button>Add user</button></form></div><div class="card tablewrap"><table><tr><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th>Action</th></tr><?php foreach(q('SELECT * FROM users ORDER BY id DESC')->fetchAll() as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['email'])?></td><td><?=h(ucfirst($r['role']))?></td><td><?=h($r['department'])?></td><td><a class="btn secondary compact" href="/?page=edit_user&amp;id=<?=$r['id']?>">Edit</a><?php if((int)$r['id']===(int)$user['id']):?><span class="muted">Current account</span><?php else:?><form method="post" class="inline-form" onsubmit="return confirm('Permanently delete this user? This cannot be undone.');"><?php hidden('delete_user',(int)$r['id']);?><button class="danger compact">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></table></div>
<?php elseif($page==='new' && $user['role']==='employee'):?>
<div class="card"><h1>Upload PDF for signature</h1><form method="post" enctype="multipart/form-data"><?php hidden('create');?><label>Title</label><input name="title" maxlength="200" required><label>PDF document (maximum 10 MB)</label><input name="pdf" type="file" accept="application/pdf,.pdf" required><label>Notes (optional)</label><textarea name="body"></textarea><label>Assigned department head</label><select name="head_id" required><option value="">Choose head</option><?php foreach(q("SELECT id,name FROM users WHERE role='head' AND department=? ORDER BY name",[$user['department']])->fetchAll() as $r):?><option value="<?=$r['id']?>"><?=h($r['name'])?></option><?php endforeach;?></select><button>Save PDF draft</button></form></div>
<?php elseif($page==='view'):?>
<?php $d=document((int)($_GET['id']??0));if(!permitted($d,$user))throw new RuntimeException('Access denied.');$owner=(int)$d['employee_id']===(int)$user['id'];$head=(int)$d['head_id']===(int)$user['id'];$es=signature((int)$d['id'],(int)$d['version'],'employee');$hs=signature((int)$d['id'],(int)$d['version'],'head'); ?>
<?php if($d['status']==='approved'):?><div class="card approved-document"><div class="approved-heading"><div><span class="approval-seal">✓</span><div><h2>Approved document</h2><p>Final PDF with the employee and department-head signatures.</p></div></div><a class="btn" href="/?page=pdf&amp;id=<?=$d['id']?>">Download signed PDF</a></div><iframe class="approved-viewer" src="/?page=approved_preview&amp;id=<?=$d['id']?>" title="Approved signed PDF"></iframe></div><?php endif;?>
<?php if(!empty($d['original_pdf'])):?><div class="card"><h2>Uploaded PDF</h2><p><a class="btn" href="/?page=file&id=<?=$d['id']?>" target="_blank" rel="noopener">Open <?=h($d['original_name']?:'PDF document')?></a></p><small>Review this document before signing.</small></div><?php else:?><div class="alert">This request was created before PDF uploads were enabled. Upload its PDF under Edit draft before signing.</div><?php endif;?>
<div class="card"><h1><?=h($d['title'])?></h1><p><b><?=h($d['reference'])?></b> · <span class="tag"><?=h(strtoupper($d['status']))?></span> · Version <?=$d['version']?></p><p><b>Employee:</b> <?=h($d['employee_name'])?> · <b>Department:</b> <?=h($d['department'])?> · <b>Assigned Head:</b> <?=h($d['head_name'])?></p><hr><div class="docbody"><?=h($d['body'])?></div><hr><div class="row"><div><b>Employee signature</b><p><?php if($es):?><img class="signature" src="/?page=signature&id=<?=$d['id']?>&kind=employee" alt="Employee signature"><?php else:?>Not yet signed<?php endif;?></p><?php if($d['employee_signed_at']):?><small class="date-time"><?=h(formatted_date($d['employee_signed_at']))?><br><?=h(formatted_time($d['employee_signed_at']))?></small><?php endif;?></div><div><b>Department Head signature</b><p><?php if($hs):?><img class="signature" src="/?page=signature&id=<?=$d['id']?>&kind=head" alt="Head signature"><?php else:?>Not yet signed<?php endif;?></p><?php if($d['head_signed_at']):?><small class="date-time"><?=h(formatted_date($d['head_signed_at']))?><br><?=h(formatted_time($d['head_signed_at']))?></small><?php endif;?></div></div><?php if($d['status']==='approved'):?><a class="btn" href="/?page=pdf&id=<?=$d['id']?>">Download signed PDF</a><?php endif;?></div>
<?php if($owner&&in_array($d['status'],['draft','returned'],true)):?><div class="card"><h2>Edit draft</h2><form method="post" enctype="multipart/form-data"><?php hidden('update',(int)$d['id']);?><label>Title</label><input name="title" value="<?=h($d['title'])?>" required><label>Replace PDF (optional, maximum 10 MB)</label><input name="pdf" type="file" accept="application/pdf,.pdf"><label>Notes (optional)</label><textarea name="body"><?=h($d['body'])?></textarea><button class="secondary">Save changes (new version)</button></form><h2>Sign and submit</h2><form method="post" data-sign-form><?php hidden('submit',(int)$d['id']);?><input type="hidden" name="signature"><input type="hidden" name="page_num"><input type="hidden" name="x_pct"><input type="hidden" name="y_pct"><input type="hidden" name="width_pct"><input type="hidden" name="height_pct"><label>Draw your signature</label><canvas data-signature></canvas><button type="button" class="secondary" data-clear>Clear</button><button type="button" data-place>Place signature on PDF</button><div class="pdf-editor" data-pdf-url="/?page=file&id=<?=$d['id']?>"><div class="pdf-toolbar"><button type="button" data-zoom-out>−</button><b data-zoom-label>100%</b><button type="button" data-zoom-in>+</button><span>Drag the signature to position it. Use the corner handle to resize.</span></div><div class="pdf-pages" data-pdf-pages></div></div><button>Submit to Department Head</button></form></div><?php endif;?>
<?php if($head&&$d['status']==='pending'&&$user['role']==='head'):?><div class="card"><h2>Department Head decision</h2><p>The PDF below already includes the employee's signature. Review it before adding your approval signature.</p><form method="post" data-sign-form><?php hidden('approve',(int)$d['id']);?><input type="hidden" name="signature"><input type="hidden" name="page_num"><input type="hidden" name="x_pct"><input type="hidden" name="y_pct"><input type="hidden" name="width_pct"><input type="hidden" name="height_pct"><label>Draw your signature</label><canvas data-signature></canvas><button type="button" class="secondary" data-clear>Clear</button><button type="button" data-place>Place signature on PDF</button><div class="pdf-editor" data-pdf-url="/?page=preview&amp;id=<?=$d['id']?>"><div class="pdf-toolbar"><button type="button" data-zoom-out>−</button><b data-zoom-label>100%</b><button type="button" data-zoom-in>+</button><span>Drag the signature to position it. Use the corner handle to resize.</span></div><div class="pdf-pages" data-pdf-pages></div></div><button>Approve and sign</button></form><hr><form method="post"><?php hidden('return',(int)$d['id']);?><label>Return / reject remarks</label><textarea name="remarks" required></textarea><button class="secondary">Return for correction</button><button class="danger" name="op" value="reject">Reject permanently</button></form></div><?php endif;?>
<div class="card"><h2>Approval history</h2><div class="tablewrap"><table><tr><th>Action</th><th>By</th><th>Remarks</th><th>Date and time</th></tr><?php foreach(q('SELECT a.*,u.name FROM approval_history a JOIN users u ON u.id=a.actor_id WHERE a.document_id=? ORDER BY a.id DESC',[$d['id']])->fetchAll() as $r):?><tr><td><?=h(ucfirst($r['action']))?></td><td><?=h($r['name'])?></td><td><?=h($r['remarks'])?></td><td><span class="date-time"><?=h(formatted_date($r['created_at']))?><br><small><?=h(formatted_time($r['created_at']))?></small></span></td></tr><?php endforeach;?></table></div></div>
<?php elseif($page==='signature'):?><?php /* handled in pre-render block below */ ?>
<?php elseif($page==='dashboard'):?>
<h1>Welcome, <?=h($user['name'])?></h1><p class="muted">Role: <?=h(ucfirst($user['role']))?> · Department: <?=h($user['department'])?></p><?php $where=$user['role']==='admin'?'1=1':($user['role']==='head'?'head_id=?':'employee_id=?');$params=$user['role']==='admin'?[]:[$user['id']];$docs=q('SELECT d.*,e.name employee_name,h.name head_name FROM documents d JOIN users e ON e.id=d.employee_id JOIN users h ON h.id=d.head_id WHERE '.$where.' ORDER BY d.updated_at DESC',$params)->fetchAll();$counts=array_count_values(array_column($docs,'status'));?><div class="stats"><?php foreach(['draft','pending','returned','rejected','approved'] as $status):?><div class="card"><small><?=h(ucfirst($status))?></small><h2><?=$counts[$status]??0?></h2></div><?php endforeach;?></div><div class="card"><h2>Documents</h2><div class="tablewrap"><table><tr><th>Reference</th><th>Title</th><th>Employee</th><th>Assigned Head</th><th>Status</th><th>Action</th></tr><?php foreach($docs as $r):?><tr><td><?=h($r['reference'])?></td><td><?=h($r['title'])?></td><td><?=h($r['employee_name'])?></td><td><?=h($r['head_name'])?></td><td><span class="tag"><?=h($r['status'])?></span></td><td><a class="btn secondary compact" href="/?page=view&amp;id=<?=$r['id']?>">View</a><?php if($user['role']==='admin'&&$r['status']!=='approved'):?><a class="btn secondary compact" href="/?page=edit_document&amp;id=<?=$r['id']?>">Edit</a><?php endif;?><?php if($user['role']==='admin'):?><form method="post" class="inline-form" onsubmit="return confirm('Permanently delete this document and all related signatures and history?');"><?php hidden('delete_document',(int)$r['id']);?><button class="danger compact">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$docs):?><p class="muted">No documents yet.</p><?php endif;?></div></div>
<?php else:?><div class="card">Page not found. <a href="/">Go to dashboard</a></div><?php endif;?></main><footer>SignFlow · Internal document approval system</footer><script src="/assets/signature.js?v=5"></script></body></html>
